class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = members.copy()
        # Track total amount each member has paid
        self.total_paid = {member: 0.0 for member in self.members}
        # Track total amount each member should pay (for expenses they participated in)
        self.total_owed = {member: 0.0 for member in self.members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if amount <= 0:
            raise ValueError("Expense amount must be positive")

        if payer not in self.members:
            raise ValueError(f"Payer '{payer}' is not a group member")

        if participants is None:
            participants = self.members
        else:
            for participant in participants:
                if participant not in self.members:
                    raise ValueError(f"Participant '{participant}' is not a group member")

        if not participants:
            raise ValueError("At least one participant is required")

        # Add to payer's total paid
        self.total_paid[payer] += amount

        # Split the expense equally among participants
        share = amount / len(participants)
        for participant in participants:
            self.total_owed[participant] += share

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        balances = {}
        for member in self.members:
            # Balance = total_paid - total_owed
            # If positive: member paid more than their share, so they are owed money
            # If negative: member paid less than their share, so they owe money
            balances[member] = self.total_paid[member] - self.total_owed[member]
        return balances

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        balances = self.balances()

        # Separate debtors (negative balance) and creditors (positive balance)
        debtors = []  # (member, amount_owed)
        creditors = []  # (member, amount_owed)

        for member, balance in balances.items():
            if balance < 0:
                debtors.append((member, -balance))  # store as positive amount owed
            elif balance > 0:
                creditors.append((member, balance))

        # Sort debtors by amount owed (largest first) and creditors by amount owed (largest first)
        # This helps minimize number of payments
        debtors.sort(key=lambda x: x[1], reverse=True)
        creditors.sort(key=lambda x: x[1], reverse=True)

        payments = []

        # Process payments until all debts are settled
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            debtor, debtor_amount = debtors[i]
            creditor, creditor_amount = creditors[j]

            # Determine payment amount (minimum of what debtor owes and what creditor is owed)
            payment_amount = min(debtor_amount, creditor_amount)

            # Only include payments >= 1.00
            if payment_amount >= 1.00:
                payments.append((debtor, creditor, round(payment_amount, 2)))

            # Update remaining amounts
            debtors[i] = (debtor, debtor_amount - payment_amount)
            creditors[j] = (creditor, creditor_amount - payment_amount)

            # Move to next debtor if fully settled
            if debtors[i][1] < 1e-9:  # Handle floating point precision
                i += 1
            # Move to next creditor if fully settled
            if creditors[j][1] < 1e-9:
                j += 1

        return payments
